from requests import Session, RequestException
import time

class RetrySession(Session):
    def __init__(self, max_attempts=2, base_backoff=0.15, max_backoff=2.0):
        super().__init__()
        self.max_attempts = max_attempts
        self.base_backoff = base_backoff
        self.max_backoff = max_backoff

    def request(self, method, url, **kwargs):
        attempt = 0
        while True:
            try:
                resp = super().request(method, url, timeout=kwargs.get('timeout', 8), **kwargs)
                if resp.status_code >= 500 and attempt < self.max_attempts:
                    raise RequestException(f"server error: {resp.status_code}")
                return resp
            except RequestException as e:
                attempt += 1
                if attempt > self.max_attempts:
                    raise
