JavaScript fallback pattern (node fetch example):

const fetch = require('node-fetch');

async function callWithFallback(url, opts, fallbackHandler) {
  try {
    const res = await fetch(url, { ...opts, timeout: 8000 });
    if (!res.ok && res.status >= 500) throw new Error('upstream server error');
    return await res.json();
  } catch (err) {
    // local cache attempt
    const cached = await fallbackHandler.getFromCache();
    if (cached) return cached;
    // local stub fallback
    const stub = await fallbackHandler.getLocalStub();
    if (stub) return stub;
    // final: surface degraded UX to caller
    return { error: 'service_unavailable', message: 'Please try again later' };
  }
}
